// Load data and initialize visualization
let allStocks = [];
let currentHighlighted = null;

const svg = d3.select('#bubble-chart');
const width = +svg.attr('width');
const height = +svg.attr('height');

// Color scale for sectors
const sectorColors = {
    'Information Technology': '#3498db',
    'Financials': '#e74c3c',
    'Healthcare': '#2ecc71',
    'Industrials': '#f39c12',
    'Consumer Discretionary': '#9b59b6',
    'Energy': '#1abc9c',
    'Utilities': '#34495e',
    'Real Estate': '#e67e22',
    'Materials': '#95a5a6',
    'Consumer Staples': '#16a085',
    'Communication Services': '#d35400',
    'ETF': '#bdc3c7'
};

// Load stock data
fetch('data/stocks.json')
    .then(response => response.json())
    .then(data => {
        allStocks = data;
        initializeBubbleChart();
        initializeTable();
    });

function initializeBubbleChart() {
    // Prepare data for visualization
    // Filter out ETFs (they have no marketCap) and assign uniform size
    const minRadius = 15;
    const maxRadius = 80;

    const dataWithSize = allStocks.map(stock => {
        let radius;
        if (stock.marketCap === null) {
            // ETF - uniform size
            radius = minRadius + 10;
        } else {
            // Scale market cap to radius
            const minMarketCap = Math.min(...allStocks.filter(s => s.marketCap).map(s => s.marketCap));
            const maxMarketCap = Math.max(...allStocks.filter(s => s.marketCap).map(s => s.marketCap));
            radius = minRadius + ((stock.marketCap - minMarketCap) / (maxMarketCap - minMarketCap)) * (maxRadius - minRadius);
        }
        return {
            ...stock,
            radius: radius,
            x: width / 2 + (Math.random() - 0.5) * 100,
            y: height / 2 + (Math.random() - 0.5) * 100
        };
    });

    // Create force simulation
    const simulation = d3.forceSimulation(dataWithSize)
        .force('x', d3.forceX(d => {
            // Position by sector on x-axis
            const sectorIndex = Object.keys(sectorColors).indexOf(d.sector);
            return (sectorIndex + 1) * (width / (Object.keys(sectorColors).length + 1));
        }).strength(0.5))
        .force('y', d3.forceY(height / 2).strength(0.3))
        .force('collide', d3.forceCollide(d => d.radius + 2).strength(0.8))
        .force('charge', d3.forceManyBody().strength(-50))
        .on('tick', ticked);

    // Create bubble group
    const bubbleGroup = svg.selectAll('.bubble')
        .data(dataWithSize, d => d.ticker)
        .enter()
        .append('circle')
        .attr('class', 'bubble')
        .attr('cx', d => d.x)
        .attr('cy', d => d.y)
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector] || '#95a5a6')
        .on('mouseover', function(event, d) {
            // Only show tooltip for non-ETFs
            if (d.marketCap !== null) {
                showTooltip(event, d);
            }
        })
        .on('mousemove', function(event) {
            moveTooltip(event);
        })
        .on('mouseout', hideTooltip)
        .on('click', function(event, d) {
            highlightBubble(d.ticker);
            highlightTableRow(d.ticker);
        });

    // Add labels to bubbles
    const labels = svg.selectAll('.bubble-label')
        .data(dataWithSize, d => d.ticker)
        .enter()
        .append('text')
        .attr('class', 'bubble-label')
        .attr('x', d => d.x)
        .attr('y', d => d.y)
        .text(d => d.ticker)
        .attr('font-size', d => {
            // Scale font size based on bubble size
            return Math.max(9, Math.min(14, d.radius / 4)) + 'px';
        });

    function ticked() {
        bubbleGroup
            .attr('cx', d => d.x)
            .attr('cy', d => d.y);

        labels
            .attr('x', d => d.x)
            .attr('y', d => d.y);
    }

    // Create legend
    const uniqueSectors = [...new Set(dataWithSize.map(d => d.sector))].sort();
    const legendContainer = d3.select('#legend');

    uniqueSectors.forEach(sector => {
        const legendItem = legendContainer.append('div')
            .attr('class', 'legend-item');

        legendItem.append('div')
            .attr('class', 'legend-color')
            .style('background-color', sectorColors[sector]);

        legendItem.append('span')
            .text(sector);
    });
}

function initializeTable() {
    const tableBody = d3.select('#table-body');

    const rows = tableBody.selectAll('tr')
        .data(allStocks, d => d.ticker)
        .enter()
        .append('tr')
        .on('click', function(event, d) {
            highlightBubble(d.ticker);
            highlightTableRow(d.ticker);
        });

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.fullName);
    rows.append('td').text(d => d.sector);
    rows.append('td')
        .text(d => {
            if (d.marketCap === null) {
                return 'N/A';
            }
            return formatMarketCap(d.marketCap);
        })
        .style('text-align', 'right');
}

function formatMarketCap(value) {
    if (value === null || value === undefined) return 'N/A';

    const units = ['', 'B', 'T'];
    let unitIndex = 0;
    let num = value;

    while (num >= 1000 && unitIndex < units.length - 1) {
        num /= 1000;
        unitIndex++;
    }

    // Round to 2 decimal places
    return num.toFixed(2) + units[unitIndex];
}

function showTooltip(event, d) {
    const tooltip = d3.select('#tooltip');
    const content = `
        <strong>${d.ticker}</strong><br/>
        ${d.fullName}<br/>
        ${d.sector}
    `;

    tooltip
        .html(content)
        .classed('visible', true);

    moveTooltip(event);
}

function moveTooltip(event) {
    const tooltip = d3.select('#tooltip');
    tooltip
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY + 10) + 'px');
}

function hideTooltip() {
    d3.select('#tooltip').classed('visible', false);
}

function highlightBubble(ticker) {
    // Remove previous highlight
    d3.selectAll('.bubble').classed('highlighted', false);

    // Add highlight to clicked bubble
    d3.selectAll('.bubble').filter(d => d.ticker === ticker).classed('highlighted', true);

    currentHighlighted = ticker;
}

function highlightTableRow(ticker) {
    // Remove previous highlight
    d3.selectAll('#stocks-table tbody tr').classed('highlighted', false);

    // Add highlight to matching row
    d3.selectAll('#stocks-table tbody tr').filter(d => d.ticker === ticker).classed('highlighted', true);

    // Scroll to highlighted row if needed
    const tableBody = d3.select('#table-body');
    const highlightedRow = tableBody.selectAll('tr').filter(d => d.ticker === ticker);

    if (!highlightedRow.empty()) {
        const row = highlightedRow.node();
        const tableContainer = d3.select('.table-container').node();
        const rowTop = row.offsetTop;
        const rowHeight = row.offsetHeight;
        const containerTop = tableContainer.scrollTop;
        const containerHeight = tableContainer.clientHeight;

        if (rowTop < containerTop) {
            tableContainer.scrollTop = rowTop;
        } else if (rowTop + rowHeight > containerTop + containerHeight) {
            tableContainer.scrollTop = rowTop + rowHeight - containerHeight;
        }
    }
}

// Click on document to clear selection
d3.select('body').on('click', function(event) {
    // Check if click is outside both chart and table
    const clickTarget = event.target;
    const inChart = d3.select('#bubble-chart').node().contains(clickTarget);
    const inTable = d3.select('#stocks-table').node().contains(clickTarget);

    if (!inChart && !inTable && event.target.tagName !== 'CIRCLE' && event.target.tagName !== 'TR' && event.target.tagName !== 'TD') {
        // Clear highlight
        d3.selectAll('.bubble').classed('highlighted', false);
        d3.selectAll('#stocks-table tbody tr').classed('highlighted', false);
        currentHighlighted = null;
    }
});

